// Example illustrating the use of "&" symbol for explicit template routine type specification

function GetDefault<T>: T :=
  default(T);

type
  GenericType<T> = class
    constructor := exit;
    static procedure p1 := writeln(typeof(T));
  end;

begin
  // The compiler doesn't distinguish between comparison operator < and opening angle bracket
  // so we need to use "&" to escape "<"
  var o := GetDefault&<byte>;

  // For template types - usually "&" is not needed
  var a := new GenericType<word>;

  // However for static method call - it must be placed
  GenericType&<real>.p1;

end.

