type Months = (January,February,March,April,May,June,
  July,August,September,October,November,December);

begin
  var m: Months := February;
  writeln(m);
  // Using enumerated type constants after type name is convenient: after dot intellisense shows list of constants
  m := Months.April;
  Println('Next month:',m);
  Inc(m);
  Println('Next month:',m);
  m := Succ(m);  
  Println('Next month:',m);
  m := Pred(m);  
  Println('Previous month:',m);
  Dec(m);
  Println('Previous month:',m);
  Println('Its ordinal number (numbering - from zero):',Ord(m));
  // No error
