  for var y := 0 to dimy-1 do
  begin
    for var x := 0 to dimx-1 do
    begin
      var c := f.ReadChar;
      a[y,x]:= if c='*' then 1 else 0;
    end;
    f.Readln  
  end;
  f.Close;
end;

procedure Draw(a: array [,] of integer);
begin
  for var y := 0 to a.RowCount-1 do
  for var x := 0 to a.ColCount-1 do
    DrawCell(a,x,y);
end;

