var
  configuration,NeighborsA,NeighborsB: array [0..n+1,0..m+1] of byte;
  updateA,updateB: array [1..nk,1..mk] of boolean;
  CountCells: integer;
  updateFlag: boolean;
  generation: integer;
  configurationVisual: DrawingVisual;
  infoVisual: DrawingVisual;

