END.

function f(x: real) := exp(x) - 4;

function BisectionMethod(a, b, eps: real): real;
begin
  var fa := f(a);
  while abs(b - a) > eps do
  begin
    var c := (a + b) / 2;
    var fc := f(c);
    if fc = 0 then
      break;
    if fa * fc < 0 then
      b := c
    else
      (a, fa) := (c, fc);
  end;
  Result := (a + b) / 2;
end;

begin
  var (a, b) := (0.0, 3.0);
  var eps := 0.000001;
  var root := BisectionMethod(a, b, eps);
  Println('Equation root:', root);
end.

