begin
  // In-block variable declarations
  var s: real := 1.0;

  // Variable declaration in loop header (variable lifetime - until end of loop body)
  for var j: integer := 1 to 10 do
    s += j; // += operation for numbers

  var p := 1;

  // Variable declaration in loop header with automatic type inference
  for var j := 1 to 10 do
    p *= j; // *= operation

  var str := '';
  for var c: char := 'a' to 'z' do
    str += c; // += operation for strings

end.

