type 
  TriangleStamp = auto class
    x,y,w,orient: integer;
    procedure Stamp;
    begin
      MoveTo(x,y);
      var dx := w;
      var dy := w;
      case orient of
     2: dx := -dx;
     3: dy := -dy;
     4: begin dx := -dx; dy := -dy; end;
      end;
      LineTo(x+dx,y);
      LineTo(x,y+dy);
      LineTo(x,y);      
    end;
    procedure MoveOn(dx,dy: integer);
    begin
      x += dx; y += dy;
    end;
  end;

