 var
   i     : Integer;
   Stars : array [1..MAX_STARS] of TStar;
   scr_W : Integer;
   scr_H : Integer;
   time, dt : Integer;

   procedure SetPix(c: Integer);
   var
     sx, sy : Integer;
   begin
   try
     sx := trunc(scr_W / 2 + Stars[i].X * 200 / (Stars[i].Z + 200));
     sy := trunc(scr_H / 2 - Stars[i].Y * 200 / (Stars[i].Z + 200));
     except
     end;

     try
      SetPixel(sx, sy, Color.FromArgb(c, c, c));
     except
     end;
   end;

 begin
   MaximizeWindow();
   scr_W := Window.Width;  
   scr_H := Window.Height;

