function Iterate<T>(first, second: T; next: (T,T)->T): sequence of T;
begin
  yield first;
  yield second;
  while True do
  begin
    var nxt := next(first, second);
    yield nxt;
    first := second;
    second := nxt;
  end;
end;

function SeqGen<T>(count: integer; first: T; next: T->T): sequence of T;
begin
  if count < 1 then
    raise new System.ArgumentOutOfRangeException('count', count, 'Parameter must be > 0');
  Result := Iterate(first, next).Take(count);
end;

function ArrGen<T>(count: integer; first, second: T; next: (T,T) ->T): array of T;
begin
  if count < 2 then
    raise new System.ArgumentOutOfRangeException('count', count, 'Parameter must be > 1');
  var a := new T[count];
  a[0] := first;
  a[1] := second;
  for var i := 2 to a.Length - 1 do
    a[i] := next(a[i - 2], a[i - 1]);
  Result := a;
end;

