function MatrSlice<T>(Self: array[,] of T; FromRow, ToRow, FromCol, ToCol: integer): array[,] of T; extensionmethod;
begin
  if not InR(FromRow,0,Self.RowCount-1) then  
    raise new System.ArgumentOutOfRangeException('FromRow is out of range for the matrix row indices',new Exception);
  if not InR(ToRow,0,Self.RowCount-1) then      raise new System.ArgumentOutOfRangeException('ToRow is out of range for the matrix row indices',new Exception);
  if not InR(FromCol,0,Self.ColCount-1) then  
    raise new System.ArgumentOutOfRangeException('FromCol is out of range for the matrix column indices',new Exception);
  if not InR(ToCol,0,Self.ColCount-1) then  
    raise new System.ArgumentOutOfRangeException('ToCol is out of range for the matrix column indices',new Exception);
  Result := new T[ToRow-FromRow+1, ToCol-FromCol+1];
  var r := 0;
  for var ir:=FromRow to ToRow do
  begin
    var c := 0;
    for var jc:=FromCol to ToCol do
    begin
      Result[r, c] := Self[ir, jc];
      c += 1;
    end;
    r += 1;
  end
end;

