function ParenthesesValidator(const s: string): boolean;
begin
  var stack := new Stack<char>;
  var pairs := new Dictionary<char, char>;
  pairs.Add(')', '(');
  pairs.Add(']', '[');
  pairs.Add('}', '{');
  foreach var ch in s do
    if pairs.ContainsKey(ch) then
    begin
      if stack.Count = 0 then
        exit(False);
      var top := stack.Pop;
      if top <> pairs[ch] then
        exit(False);
    end
    else
      stack.Push(ch);
  Result := stack.Count = 0;
end;

function PalindromeSublists(const lst: array of integer): integer;
begin
  Result := 0;
  if lst.Length = 0 then
    exit(0);
  for var i := 0 to High(lst) do
    for var j := i to High(lst) do
    begin
      var left := i;
      var right := j;
      var isPalindrome := True;
      while left < right do
      begin
        if lst[left] <> lst[right] then
        begin
          isPalindrome := False;
          break;
        end;
        left += 1;
        right -= 1;
      end;
      if isPalindrome then
        Result += 1;
    end;
end;

