  var count := 0;
  for var i := 0 to lst.Length - sublst.Length do
  begin
    var matches := True;
    for var j := 0 to sublst.Length - 1 do
      if lst[i + j] <> sublst[j] then
      begin
        matches := False;
        break;
      end;
    if matches then
      count += 1;
  end;
  Result := count;
end;

function MinInsertionsToPalindrome(const s: string): integer;
begin
  var n := s.Length;
  if n = 0 then
    exit(0);
  var chars := s.ToCharArray;
  var dp := new integer[n, n];
  for var i := n - 1 downto 0 do
  begin
    dp[i, i] := 1;
    for var j := i + 1 to n - 1 do
      if chars[i] = chars[j] then
        if j = i + 1 then
          dp[i, j] := 2
        else
          dp[i, j] := dp[i + 1, j - 1] + 2
      else
        dp[i, j] := Max(dp[i + 1, j], dp[i, j - 1]);
  end;
  Result := n - dp[0, n - 1];
end;

