procedure DFS(var grid: array[,] of integer; r, c: integer);
begin
  if (r < 0) or (c < 0) or (r >= grid.GetLength(0)) or (c >= grid.GetLength(1)) then
    exit;
  if grid[r, c] <> 1 then
    exit;
  grid[r, c] := -1;
  DFS(grid, r + 1, c);
  DFS(grid, r - 1, c);
  DFS(grid, r, c + 1);
  DFS(grid, r, c - 1);
end;

function FindIslands(var grid: array[,] of integer): integer;
begin
  var rows := grid.GetLength(0);
  var cols := grid.GetLength(1);
  var count := 0;
  for var r := 0 to rows - 1 do
    for var c := 0 to cols - 1 do
      if grid[r, c] = 1 then
      begin
        count += 1;
        DFS(grid, r, c);
      end;
  Result := count;
end;

