function OneInsertAway(const longer, shorter: string): boolean;
begin
  var i := 0;
  var j := 0;
  var edits := 0;
  var a := longer.ToCharArray;
  var b := shorter.ToCharArray;
  while (i < a.Length) and (j < b.Length) do
    if a[i] = b[j] then
    begin
      i += 1;
      j += 1;
    end
    else
    begin
      edits += 1;
      if edits > 1 then
        exit(False);
      i += 1;
    end;
  Result := True;
end;

function IsOneEditAway(const s1, s2: string): boolean;
begin
  var diff := Abs(s1.Length - s2.Length);
  if diff > 1 then
    exit(False);
  if diff = 0 then
  begin
    var edits := 0;
    for var i := 1 to s1.Length do
      if s1[i] <> s2[i] then
      begin
        edits += 1;
        if edits > 1 then
          exit(False);
      end;
    Result := edits = 1;
  end
  else if s1.Length > s2.Length then
    Result := OneInsertAway(s1, s2)
  else
    Result := OneInsertAway(s2, s1);
end;

