function BinRepresentation(num: integer): string;
begin
  if num = 0 then
    exit('0');
  var builder := new StringBuilder;
  var value := num;
  while value > 0 do
  begin
    builder.Insert(0, char(ord('0') + (value mod 2)));
    value := value div 2;
  end;
  Result := builder.ToString;
end;

