function TopFrequent(const nums: array of integer; k: integer): array of integer;
begin
  var counts := new Dictionary<integer, integer>;
  var firstIndex := new Dictionary<integer, integer>;
  for var i := 0 to nums.Length - 1 do
  begin
    var value := nums[i];
    if counts.ContainsKey(value) then
      counts[value] += 1
    else
    begin
      counts[value] := 1;
      firstIndex[value] := i;
    end;
  end;
  var ordered := new List<integer>(counts.Keys);
  ordered.Sort((a, b) ->
  begin
    var cmp := counts[b].CompareTo(counts[a]);
    if cmp <> 0 then 
      Result := cmp
    else
      Result := firstIndex[a].CompareTo(firstIndex[b]);
  end);
  var resultList := new List<integer>;
  for var i := 0 to Min(k, ordered.Count) - 1 do
    resultList.Add(ordered[i]);
  Result := resultList.ToArray;
end;

function SplitList(const xs: array of integer): array of array of integer;
begin
  var resultList := new List<array of integer>;
  for var i := 1 to xs.Length - 1 do
  begin
    var left := new integer[i];
    var right := new integer[xs.Length - i];
    &Array.Copy(xs, 0, left, 0, i);
    &Array.Copy(xs, i, right, 0, xs.Length - i);
    resultList.Add(left);
    resultList.Add(right);
  end;
  Result := resultList.ToArray;
end;

