function IsPostorderBST(const postorder: array of integer): boolean;

  function Helper(left, right: integer): boolean;
  begin
    if left >= right then
      exit(True);
    var pivot := postorder[right];
    var mid := left;
    while (mid < right) and (postorder[mid] < pivot) do
      mid += 1;
    for var i := mid to right - 1 do
      if postorder[i] < pivot then
        exit(False);
    Result := Helper(left, mid - 1) and Helper(mid, right - 1);
  end;

begin
  if postorder.Length = 0 then
    exit(True);
  Result := Helper(0, postorder.Length - 1);
end;

uses System.Collections.Generic;

function FindHistogramArea(const heights: array of integer): integer;
begin
  var stack := new Stack<integer>;
  var index := 0;
  var maxArea := 0;
  while index < heights.Length do
    if (stack.Count = 0) or (heights[stack.Peek] <= heights[index]) then
    begin
      stack.Push(index);
      index += 1;
    end
    else
    begin
      var top := stack.Pop;
      var width := index;
      if stack.Count > 0 then
        width -= stack.Peek + 1;
      var area := heights[top] * width;
      if area > maxArea then
        maxArea := area;
    end;
  while stack.Count > 0 do
  begin
    var top := stack.Pop;
    var width := index;
    if stack.Count > 0 then
      width -= stack.Peek + 1;
    var area := heights[top] * width;
    if area > maxArea then
      maxArea := area;
  end;
  Result := maxArea;
end;

