function ReverseOnlyLetters(const value: string): string;
begin
  var chars := value.ToCharArray;
  var left := 0;
  var right := chars.Length - 1;
  while left < right do
  begin
    while (left < right) and not chars[left].IsLetter do
      left += 1;
    while (left < right) and not chars[right].IsLetter do
      right -= 1;
    if left < right then
    begin
      var temp := chars[left];
      chars[left] := chars[right];
      chars[right] := temp;
      left += 1;
      right -= 1;
    end;
  end;
  Result := new string(chars);
end;

function RotateCipher(const text: string; shift: integer): string;
begin
  var builder := new System.Text.StringBuilder;
  foreach var ch in text do
    if ch.IsLetter then
    begin
      var offset := ord('a');
      if ch.IsUpper then
        offset := ord('A');
      var rotated := char(offset + (ord(ch) - offset + shift) mod 26);
      builder.Append(rotated);
    end
    else
      builder.Append(ch);
  Result := builder.ToString;
end;

