uses System.Collections.Generic;

function IsPossibleDivide(const nums: array of integer; k: integer): boolean;
begin
  if k = 0 then
    exit(False);
  if nums.Length mod k <> 0 then
    exit(False);
  var counts := new SortedDictionary<integer, integer>;
  foreach var num in nums do
    if counts.ContainsKey(num) then
      counts[num] += 1
    else
      counts[num] := 1;
  while counts.Count > 0 do
  begin
    var start := counts.Keys.First;
    for var offset := 0 to k - 1 do
    begin
      var value := start + offset;
      if (not counts.ContainsKey(value)) then
        exit(False);
      counts[value] -= 1;
      if counts[value] = 0 then
        counts.Remove(value);
    end;
  end;
  Result := True;
end;

function DoCirclesIntersect(const center1, center2: (real, real); radius1, radius2: real): boolean;
begin
  var dx := center1.Item1 - center2.Item1;
  var dy := center1.Item2 - center2.Item2;
  var distance := Sqrt(dx * dx + dy * dy);
  Result := distance < (radius1 + radius2);
end;

