function NextLookAndSay(const current: string): string;
begin
  if current = '' then
    exit('');
  var builder := new StringBuilder;
  var chars := current.ToCharArray;
  var i := 0;
  while i < chars.Length do
  begin
    var j := i;
    while (j < chars.Length) and (chars[j] = chars[i]) do
      j += 1;
    builder.Append((j - i).ToString);
    builder.Append(chars[i]);
    i := j;
  end;
