function CoinsRequired(amount: integer; const coins: array of integer): integer;
begin
  var dp := new integer[amount + 1];
  for var i := 1 to amount do
    dp[i] := integer.MaxValue div 2;
  dp[0] := 0;
  foreach var coin in coins do
    for var value := coin to amount do
      dp[value] := Min(dp[value], dp[value - coin] + 1);
  if dp[amount] >= integer.MaxValue div 2 then
    Result := -1
  else
    Result := dp[amount];
end;

