uses System, System.Text;

function RecommendUsername(idValue: string): string;
begin
  var lower := idValue.ToLower;
  var filtered := new StringBuilder;
  foreach var ch in lower do
    if Char.IsLower(ch) or Char.IsDigit(ch) or (ch in ['-', '_', '.']) then
      filtered.Append(ch);
  var collapsed := new StringBuilder;
  var prevDot := False;
  foreach var ch in filtered.ToString do
    if ch = '.' then
    begin
      if not prevDot then
        collapsed.Append(ch);
      prevDot := True;
    end
    else
    begin
      collapsed.Append(ch);
      prevDot := False;
    end;
  var candidate := collapsed.ToString.Trim('.');
  if candidate = '' then
    candidate := 'a';
  if candidate.Length > 15 then
  begin
    candidate := candidate.Substring(0, 15).Trim('.');
    if candidate = '' then
      candidate := 'a';
  end;
  while candidate.Length < 3 do
    candidate += candidate[^1];
  Result := candidate;
end;

