function RepeatedSubstringPattern(const s: string): boolean;
begin
  if s.Length <= 1 then
    exit(False);
  for var len := 1 to s.Length div 2 do
    if s.Length mod len = 0 then
    begin
      var chunk := s.Substring(0, len);
      var builder := new StringBuilder;
      var repeats := s.Length div len;
      for var k := 1 to repeats do
        builder.Append(chunk);
      if builder.ToString = s then
        exit(True);
    end;
  Result := False;
end;

