function MaxPoints(const nums: array of integer): integer;
begin
  if nums.Length = 0 then
    exit(0);
  var values := new List<integer>;
  values.AddRange(nums);
  while values.Count > 1 do
  begin
    var maxSum := integer.MinValue;
    var maxIndex := 0;
    for var i := 0 to values.Count - 2 do
    begin
      var candidate := values[i] + values[i + 1];
      if candidate > maxSum then
      begin
        maxSum := candidate;
        maxIndex := i;
      end;
    end;
    values[maxIndex] := maxSum;
    values.RemoveAt(maxIndex + 1);
  end;
  Result := values[0];
end;

