function FindTargetCount(nums: array of integer; target: integer): integer;

  function BinSearch(nums: array of integer; target: integer; leftBias: boolean): integer;
  begin
    var lp := 0;
    var rp := nums.Length - 1;
    var mid := 0;
    var index := -1;
    while lp <= rp do
    begin
      mid := (lp + rp) div 2;
      if nums[mid] = target then
      begin
        index := mid;
        if leftBias then
          rp := mid - 1
        else
          lp := mid + 1;
      end
      else if nums[mid] > target then
        rp := mid - 1
      else
        lp := mid + 1;
    end;
    Result := index;
  end;

begin
  var left := BinSearch(nums, target, True);
  var right := BinSearch(nums, target, False);
  if left = -1 then
    Result := 0
  else
    Result := right - left + 1;
end;

