function CountDistinctSubarrays(arr: array of integer; k: integer): integer;

  function AtMostKDistinct(arr: array of integer; k: integer): integer;
  begin
    var count := new Dictionary<integer, integer>;
    var left := 0;
    var resultCount := 0;
    for var right := 0 to arr.Length - 1 do
    begin
      if not count.ContainsKey(arr[right]) then
        count[arr[right]] := 0;
      if count[arr[right]] = 0 then
        k -= 1;
      count[arr[right]] += 1;
      while k < 0 do
      begin
        count[arr[left]] -= 1;
        if count[arr[left]] = 0 then
          k += 1;
        left += 1;
      end;
      resultCount += right - left + 1;
    end;
    Result := resultCount;
  end;

begin
  Result := AtMostKDistinct(arr, k) - AtMostKDistinct(arr, k - 1);
end;

function MaxNestedEnvelopes(envelopes: array of (integer, integer)): integer;
begin
  envelopes := envelopes.OrderBy(e -> (e[0], -e[1])).ToArray;
  var heights := envelopes.Select(e -> e[1]).ToArray;
  var dp := new List<integer>;
  foreach var height in heights do
  begin
    var i := dp.BinarySearch(height);
    if i < 0 then
      i := -(i + 1);
    if i = dp.Count then
      dp.Add(height)
    else
      dp[i] := height;
  end;
  Result := dp.Count;
end;

function MostRepeatedElements(lst: array of integer): array of integer;
begin
  var count := new Dictionary<integer, integer>;
  foreach var i in lst do
  begin
    if count.ContainsKey(i) then
      count[i] += 1
    else
      count[i] := 1;
  end;
  var maxCount := count.Values.Max;
  Result := count.Where(p -> p.Value = maxCount).Select(p -> p.Key).ToArray;
end;

function SmallestSubarrayLength(arr: array of integer; target: integer): integer;
begin
  var start := 0;
  var minLength := integer.MaxValue;
  var currentSum := 0;
  for var endIndex := 0 to arr.Length - 1 do
  begin
    currentSum += arr[endIndex];
    while currentSum >= target do
    begin
      minLength := Min(minLength, endIndex - start + 1);
      currentSum -= arr[start];
      start += 1;
    end;
  end;
  if minLength <> integer.MaxValue then
    Result := minLength
  else
    Result := 0;
end;

