function GetGCD(x, y: integer): integer;
begin
  while y <> 0 do
  begin
    (x, y) := (y, x mod y);
  end;
  Result := x;
end;

function MaxSumSubarray(arr: array of integer; k: integer): integer;
begin
  if arr.Length < k then
  begin
    Result := 0;
    exit;
  end;
  var maxSum := arr[
      :k
    ].Sum;
  var tempSum := maxSum;
  for var i := k to arr.Length - 1 do
  begin
    tempSum := tempSum - arr[i - k
    ] + arr[i
    ];
    maxSum := Max(maxSum, tempSum);
  end;
  Result := maxSum;
end;

function StringTransformation(source, target: string): integer;
begin
  var lenSource := source.Length;
  var lenTarget := target.Length;
  var dp := new integer[lenSource + 1, lenTarget + 1
    ];
  for var i := 0 to lenSource do
    for var j := 0 to lenTarget do
    begin
      if i = 0 then
        dp[i, j
    ] := j
      else if j = 0 then
        dp[i, j
    ] := i
      else if source[i - 1
    ] = target[j - 1
    ] then
        dp[i, j
    ] := dp[i - 1, j - 1
    ]
      else
        dp[i, j
    ] := 1 + Min(Min(dp[i - 1, j
    ], dp[i, j - 1
    ]), dp[i - 1, j - 1
    ]);
    end;
  Result := dp[lenSource, lenTarget
    ];
end;

function LengthOfLongestIncreasingSubsequence(nums: array of integer): integer;
begin
  var sub := new List<integer>;
  foreach var x in nums do
  begin
    var i := sub.BinarySearch(x);
    if i < 0 then
      i := -(i + 1);
    if i = sub.Count then
      sub.Add(x)
    else
      sub[i
    ] := x;
  end;
  Result := sub.Count;
end;

function PatternMatch(s, p: string): boolean;
begin
  var dp := new boolean[s.Length + 1, p.Length + 1
    ];
  dp[
      0, 0
    ] := True;
  for var j := 1 to p.Length do
    if (p[j - 1
    ] = '*') and dp[
      0, j - 2
    ] then
      dp[
      0, j
    ] := True;
  for var i := 1 to s.Length do
    for var j := 1 to p.Length do
    begin
      if (p[j - 1
    ] = s[i - 1
    ]) or (p[j - 1
    ] = '.') then
        dp[i, j
    ] := dp[i - 1, j - 1
    ]
      else if p[j - 1
    ] = '*' then
        dp[i, j
    ] := dp[i, j - 2
    ] or (dp[i - 1, j
    ] and ((s[i - 1
    ] = p[j - 2
    ]) or (p[j - 2
    ] = '.')));
    end;
  Result := dp[s.Length, p.Length
    ];
end;

function ConvertToDigits(number: integer): array of integer;
begin
  if number = 0 then
  begin
    Result := Arr(0);
    exit;
  end;
  var digits := new List<integer>;
  while number > 0 do
  begin
    digits.Add(number mod 10);
    number := number div 10;
  end;
  digits.Reverse;
  Result := digits.ToArray;
end;

function MinRemoveParentheses(s: string): integer;
begin
  var left := 0;
  var right := 0;
  var remove := 0;
  foreach var paren in s do
  begin
    if paren = '(' then
      left += 1
    else if (paren = ')') and (left > 0) then
      left -= 1
    else
      remove += 1;
  end;
  Result := remove + left;
end;

function FindSubarrayWithGivenSum(arr: array of integer; targetSum: integer): (integer, integer);
begin
  var currSum := 0;
  var start := 0;
  for var endIndex := 0 to arr.Length - 1 do
  begin
    currSum += arr[endIndex
    ];
    while (currSum > targetSum) and (start < endIndex) do
    begin
      currSum -= arr[start
    ];
      start += 1;
    end;
    if currSum = targetSum then
    begin
      Result := (start, endIndex);
      exit;
    end;
  end;
  Result := (-1,-1);
end;

function BackspaceTyping(inputString: string): string;
begin
  var stack := new Stack<char>;
  foreach var char in inputString do
  begin
    if char <> '#' then
      stack.Push(char)
    else if stack.Count > 0 then
      stack.Pop;
  end;
  Result := new string(stack.Reverse.ToArray);
end;

function CountDivisibleBy2(n: integer): integer;
begin
  var count := 0;
  while n mod 2 = 0 do
  begin
    count += 1;
    n := n div 2;
  end;
  Result := count;
end;

function CountVowelsLocal(vowels: string; word: string): integer;
  begin
    var cnt := 0;
    foreach var c in word do
      if vowels.Contains(c) then cnt += 1;
    Result := cnt;
  end;

function MostVowels(words: array of string): array of string;
begin
  var vowels := 'aeiouAEIOU';

  var maxV := 0;
  foreach var w in words do
    maxV := Max(maxV, CountVowelsLocal(vowels, w));

  var list := new List<string>;
  foreach var w in words do
    if CountVowelsLocal(vowels, w) = maxV then
      list.Add(w);

  Result := list.ToArray;
end;

function FindWordsStartingWith(s: string; startChar: char): array of string;
begin
  var parts := s.Split(' ');
