function SumFactorialDigits(n: integer): integer;
begin
  var factorial := 1bi;
  for var i := 2 to n do
    factorial *= i;
  var sumDigits := 0;
  while factorial > 0 do
  begin
    sumDigits += integer(factorial mod 10);
    factorial := factorial div 10;
  end;
  Result := sumDigits;
end;

function TrailingZeros(n: integer): integer;
begin
  var count := 0;
  var i := 5;
  while n div i >= 1 do
  begin
    count += n div i;
    i *= 5;
  end;
  Result := count;
end;

function MaxWidthRamp(nums: array of integer): integer;
begin
  var pairs := new List<(integer, integer)>;
  for var i := 0 to nums.Length - 1 do
    pairs.Add((nums[i], i));

  pairs.Sort((a, b) -> a.Item1.CompareTo(b.Item1));

  var minIndex := MaxInt;
  var res := 0;

  foreach var p in pairs do
  begin
    var idx := p.Item2;
    res := Max(res, idx - minIndex);
    minIndex := Min(minIndex, idx);
  end;

  Result := res;
end;

function StockProfit(prices: array of integer): integer;
begin
  if prices.Length = 0 then
  begin
    Result := 0;
    exit;
  end;
  var minPrice := integer.MaxValue;
  var maxProfit := 0;
  foreach var price in prices do
  begin
    minPrice := Min(minPrice, price);
    maxProfit := Max(maxProfit, price - minPrice);
  end;
  Result := maxProfit;
end;

