begin
  var counts := new Dictionary<integer, integer>;
  foreach var num in arr do
  begin
    if counts.ContainsKey(num) then
      counts[num] += 1
    else
      counts[num] := 1;
  end;
  var resultList := new List<integer>;
  foreach var num in arr do
    if counts[num] = 1 then
      resultList.Add(num);
  Result := resultList.ToArray;
end;

function CountBinarySubstrings(s: string): integer;
begin
  var pre := 0;
  var cur := 1;
  var cnt := 0;
  for var i := 1 to s.Length - 1 do
  begin
    if s[i
    ] = s[i - 1
    ] then
      cur += 1
    else
    begin
      cnt += Min(pre, cur);
      pre := cur;
      cur := 1;
    end;
  end;
  Result := cnt + Min(pre, cur);
end;

function DistanceCovered(acceleration, time: real): real;
