function MergeSegments(segments: array of (integer, integer)): array of (integer, integer);
begin
  segments := segments.Order.ToArray;
  var merged := new List<(integer, integer)>;
  foreach var seg in segments do
  begin
    if (merged.Count = 0) or (merged.Last[
      1
    ] < seg[
      0
    ]) then
      merged.Add(seg)
    else
      merged[merged.Count - 1
    ] := (merged.Last[
      0
    ], Max(merged.Last[
      1
    ], seg[
      1
    ]));
  end;
  Result := merged.ToArray;
end;

function FileExtensionCount(files: array of string): Dictionary<string, integer>;
begin
  var extensionCount := new Dictionary<string, integer>;

  foreach var fname in files do
  begin
    var parts := fname.Split('.');
    if parts.Length > 1 then
    begin
      var ext := parts[parts.Length - 1];

      if extensionCount.ContainsKey(ext) then
        extensionCount[ext] := extensionCount[ext] + 1
      else
        extensionCount[ext] := 1;
    end;
  end;

  Result := extensionCount;
end;

function Add(a, b: integer): integer;
begin
