function MinSquares(n: integer): integer;
begin
  if n <= 3 then
  begin
    Result := n;
    exit;
  end;
  var dp := ArrFill(n + 1, 0);
  for var i := 1 to n do
  begin
    dp[i
    ] := i;
    for var j := 1 to integer(Sqrt(i)) do
      dp[i
    ] := Min(dp[i
    ], dp[i - j * j
    ] + 1);
  end;
  Result := dp[n
    ];
end;

function SwapPairs(arr: array of integer): array of integer;
begin
  for var i := 0 to arr.Length - 2 step 2 do
    Swap(arr[i
    ], arr[i + 1
    ]);
