end;

function CartesianProduct(list1, list2: array of integer): array of (integer, integer);
begin
  var product := new List<(integer, integer)>;
  foreach var x in list1 do
    foreach var y in list2 do
      product.Add((x, y));
  Result := product.ToArray;
end;

function SortMixedList(lst: array of object): array of object;
begin
  var numList := new List<integer>;
  var strList := new List<string>;

  foreach var x in lst do
  begin
    if x is integer then
      numList.Add(integer(x))
    else if x is string then
      strList.Add(string(x));
  end;

  numList.Sort;
  strList.Sort;

  var resultList := new List<object>;
  foreach var n in numList do
    resultList.Add(n);
  foreach var s in strList do
    resultList.Add(s);

  Result := resultList.ToArray;
end;

function MaxWords(sentences: array of string): integer;

