    if s[i + 1
    ] = '(' then
      stack.Push(i)
    else
    begin
      stack.Pop;
      if stack.Count = 0 then
        stack.Push(i)
      else
        longest := Max(longest, i - stack.Peek);
    end;
  end;
  Result := longest;
end;

