function IsTransformable(s, t: string): boolean;
begin
  if s.Length <> t.Length then
  begin
    Result := False;
    exit;
  end;
  var sCounter := new Dictionary<char, integer>;
  var tCounter := new Dictionary<char, integer>;
  foreach var char in s do
  begin
    if sCounter.ContainsKey(char) then
      sCounter[char
    ] += 1
    else
      sCounter[char
    ] := 1;
  end;
  foreach var char in t do
  begin
    if tCounter.ContainsKey(char) then
      tCounter[char
    ] += 1
    else
      tCounter[char
    ] := 1;
  end;
  foreach var char in tCounter.Keys do
    if (not sCounter.ContainsKey(char)) or (tCounter[char
    ] > sCounter[char
    ]) then
    begin
      Result := False;
      exit;
    end;
  var sSorted := s.ToCharArray.Order.ToArray;
  var tSorted := t.ToCharArray.Order.ToArray;
  for var i := 0 to s.Length - 1 do
    if sSorted[i
    ] <> tSorted[i
    ] then
    begin
      Result := False;
      exit;
    end;
  Result := True;
end;

function MaxPalindrome(s: string): integer;
begin
  var count := new Dictionary<char, integer>;
  foreach var c in s do
  begin
    if count.ContainsKey(c) then
      count[c] := count[c] + 1
    else
      count[c] := 1;
  end;

  var res := 0;
  var hasOdd := False;

  foreach var v in count.Values do
  begin
    if v mod 2 = 0 then
      res += v
    else
    begin
      res += v - 1;
      hasOdd := True;
    end;
  end;

  if hasOdd then
    res += 1;

  Result := res;
end;

