function GridPath(grid: array [,] of integer): integer;
begin
  var m := grid.GetLength(0);
  var n := grid.GetLength(1);
  var dp := new integer[m, n];

  if grid[0, 0] = 0 then
    dp[0, 0] := 1
  else
    dp[0, 0] := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      if grid[i, j] = 1 then
        dp[i, j] := 0
      else
      begin
        if i > 0 then
          dp[i, j] += dp[i - 1, j];
        if j > 0 then
          dp[i, j] += dp[i, j - 1];
      end;
    end;
  Result := dp[m - 1, n - 1];
end;

function SmallestPalindrome(s: string; k: integer): string;

  function ExpandAroundCenter(left, right: integer): string;
  begin
    while (left >= 1) and (right <= s.Length) and (s[left
    ] = s[right
    ]) do
    begin
      left -= 1;
      right += 1;
    end;
    Result := s.Substring(left + 1, right - left - 1);
  end;

begin
  var smallest: string := nil;
  for var i := 1 to s.Length do
  begin
    var palindrome1 := ExpandAroundCenter(i, i);
    var palindrome2 := ExpandAroundCenter(i, i + 1);
    if (palindrome1.Length >= k) and ((smallest = nil) or (palindrome1.Length < smallest.Length)) then
      smallest := palindrome1;
    if (palindrome2.Length >= k) and ((smallest = nil) or (palindrome2.Length < smallest.Length)) then
      smallest := palindrome2;
  end;
  Result := smallest;
end;

function ShiftSentence(sentence: string; n: integer): string;
begin
  var answer := new List<char>;
  for var i := 1 to sentence.Length do
  begin
    var alpha := Ord(sentence[i
    ]);
    var letter := alpha + n;
    if (65 <= alpha) and (alpha <= 90) then
    begin
      if letter > 90 then
        letter := 64 + (letter - 90);
      answer.Add(Chr(letter));
    end
    else if (97 <= alpha) and (alpha <= 122) then
    begin
      if letter > 122 then
        letter := 96 + (letter - 122);
      answer.Add(Chr(letter));
    end
    else
      answer.Add(sentence[i
    ]);
  end;
  Result := answer.JoinToString('');
end;

function ShortestDistance(mat: array [,] of integer): array [,] of integer;
begin
  var queue := new Queue<(integer, integer, integer)>;
  var seen := new HashSet<(integer, integer)>;
  for var i := 0 to mat.GetLength(0) - 1 do
    for var j := 0 to mat.GetLength(1) - 1 do
      if mat[i, j
    ] = 0 then
      begin
        queue.Enqueue((i, j,0));
        seen.Add((i, j));
      end;
  while queue.Count > 0 do
  begin
    var (i, j, steps) := queue.Dequeue;
    var directions := Arr((0,1), (1,0), (-1,0), (0,-1));
    foreach var (di, dj) in directions do
    begin
      var p := i + di;
      var q := j + dj;
      if (0 <= p) and (p < mat.GetLength(0)) and (0 <= q) and (q < mat.GetLength(1)) and not seen.Contains((p, q)) then
      begin
        seen.Add((p, q));
        queue.Enqueue((p, q, steps + 1));
        mat[p, q
] := steps + 1;
      end;
    end;
  end;
  Result := mat;
end;

