function LongestSubarrayWithinThreshold(arr: array of integer; threshold: integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;
  var maxLen := 0;
  var minVal := arr[
      0
    ];
  var maxVal := arr[
      0
    ];
  var start := 0;
  for var endIndex := 0 to arr.Length - 1 do
  begin
    minVal := Min(minVal, arr[endIndex
    ]);
    maxVal := Max(maxVal, arr[endIndex
    ]);
    while maxVal - minVal > threshold do
    begin
      if arr[start
    ] = minVal then
        minVal := arr[start + 1:endIndex + 1
    ].Min
      else if arr[start
    ] = maxVal then
        maxVal := arr[start + 1:endIndex + 1
    ].Max;
      start += 1;
    end;
    maxLen := Max(maxLen, endIndex - start + 1);
  end;
  Result := maxLen;
end;

