function MaxProductAfterCutting(n: integer): integer;
begin
  if n <= 3 then
  begin
    Result := n - 1;
    exit;
  end;
  var (a, b) := (n div 3 - 1, n mod 3);
  var p := 1000000007;
  var (x, rem) := (3,1);
  while a > 0 do
  begin
    if a mod 2 = 1 then
      rem := (rem * x) mod p;
    x := (x * x) mod p;
    a := a div 2;
  end;
  case b of
    0: Result := (rem * 3) mod p;
    1: Result := (rem * 4) mod p;
    2: Result := (rem * 6) mod p;
  end;
end;

