function MinimumOperations(nums: array of integer; start, goal: integer): integer;
begin
  var q := new Queue<(integer, integer)>;
  q.Enqueue((start,0));
  var seen := new HashSet<integer>;
  while q.Count > 0 do
  begin
    var (n, steps) := q.Dequeue;
    if n = goal then
    begin
      Result := steps;
      exit;
    end;
    if (n < 0) or (n > 1000) then
      continue;
    if n in seen then
      continue;
    seen.Add(n);
    foreach var cand in nums do
    begin
      var x := n + cand;
      var y := n - cand;
      var z := n xor cand;
      q.Enqueue((x, steps + 1));
      q.Enqueue((y, steps + 1));
      q.Enqueue((z, steps + 1));
    end;
  end;
  Result := -1;
end;

