    count += sublist.Count(x -> x = value);
  Result := count;
end;

function OverlapLength(a, b: string): integer;
begin
  var maxOverlap := 0;
  for var i := 1 to Min(a.Length, b.Length) do
  begin
    if a.EndsWith(b.Substring(0, i)) then
      maxOverlap := i;
    if b.EndsWith(a.Substring(0, i)) then
      maxOverlap := Max(maxOverlap, i);
  end;
  Result := maxOverlap;
end;

function ShortestSuperstring(s, t: string): string;
begin
  var shortestSuperstring: string := '';

  if s.Length > t.Length then
    (s, t) := (t, s);

  for var i := s.Length downto 0 do
  begin
    if s.StartsWith(t.Substring(t.Length - i)) then
    begin
      shortestSuperstring := t + s.Substring(i);
      break;
    end;
    if t.StartsWith(s.Substring(s.Length - i)) then
    begin
      shortestSuperstring := s + t.Substring(i);
      break;
    end;
  end;

  if shortestSuperstring = '' then
    shortestSuperstring := s + t;

  Result := shortestSuperstring;
end;

function FindCheapestCost(n: integer; costs: array of (integer, integer, integer)): integer;
begin
  var graph := new Dictionary<integer, List<(integer, integer)>>;
  foreach var (u, v, w) in costs do
  begin
    if not graph.ContainsKey(u) then
      graph[u] := new List<(integer, integer)>;
    if not graph.ContainsKey(v) then
      graph[v] := new List<(integer, integer)>;
    graph[u].Add((v, w));
    graph[v].Add((u, w));
  end;

  var visited := ArrFill(n, False);
  var minHeap := new List<(integer, integer)>;
  minHeap.Add((0, 0));
  var totalCost := 0;

  while minHeap.Count > 0 do
  begin
    var (cost, island) := minHeap.First;
    minHeap.RemoveAt(0);
    if visited[island] then
      continue;
    visited[island] := True;
    totalCost += cost;
    foreach var (nextIsland, nextCost) in graph[island] do
    begin
      if not visited[nextIsland] then
      begin
        minHeap.Add((nextCost, nextIsland));
        minHeap := minHeap.OrderBy(x -> x.Item1).ToList;
      end;
    end;
  end;

  Result := totalCost;
end;

function FindMostCommonBigram(text: string): (string, string);
begin
  var words := text.ToWords;
  var bigramCounts := new Dictionary<(string, string), integer>;

  for var i := 0 to words.Length - 2 do
  begin
    var bigram := (words[i], words[i + 1]);
    if bigramCounts.ContainsKey(bigram) then
      bigramCounts[bigram] += 1
    else
      bigramCounts[bigram] := 1;
  end;

  var maxBigram := bigramCounts.OrderByDescending(x -> x.Value).First.Key;
  Result := maxBigram;
end;

function UniqueOrderedList(lst: array of integer): array of integer;
begin
  var seen := new HashSet<integer>;
