function RomanToInt(s: string): integer;
begin
  var roman := new Dictionary<string, integer>;
  roman['I'] := 1; roman['V'] := 5; roman['X'] := 10; roman['L'] := 50;
  roman['C'] := 100; roman['D'] := 500; roman['M'] := 1000;
  roman['IV'] := 4; roman['IX'] := 9; roman['XL'] := 40; roman['XC'] := 90;
  roman['CD'] := 400; roman['CM'] := 900;

  var i := 1;
  var num := 0;
  while i <= s.Length do
  begin
    if (i < s.Length) and roman.ContainsKey(s.Substring(i - 1, 2)) then
    begin
      num += roman[s.Substring(i - 1, 2)];
      i += 2;
    end
    else
    begin
      num += roman[s[i].ToString];
      i += 1;
    end;
  end;
  Result := num;
end;

function SortOddIndices(lst: array of integer): array of integer;
begin
  var oddIndices := new List<integer>;
  for var i := 1 to lst.Length - 1 step 2 do
    oddIndices.Add(lst[i]);

  oddIndices.Sort;
  var res := new List<integer>;
  var oddIdx := 0;

  for var i := 0 to lst.Length - 1 do
  begin
    if i mod 2 = 0 then
      res.Add(lst[i])
    else
    begin
      res.Add(oddIndices[oddIdx]);
      oddIdx += 1;
    end;
  end;

  Result := res.ToArray;
end;

function IsLargestPalindrome(n: integer): integer;
begin
  var largestPalindrome := 0;
  var startNum := Round(Power(10, n - 1));
  var endNum := Round(Power(10, n)) - 1;

  for var i := startNum to endNum do
  begin
    for var j := i to endNum do
    begin
      var product := i * j;
      var productStr := product.ToString;
      var reversedStr := new string(productStr.Reverse.ToArray);

      if (productStr = reversedStr) and (product > largestPalindrome) then
        largestPalindrome := product;
    end;
  end;
  Result := largestPalindrome;
end;

function MaxConsecutive1s(nums: array of integer; k: integer): integer;
begin
  var left := 0;

  for var right := 0 to nums.Length - 1 do
  begin
    if nums[right] = 0 then
      k -= 1;

    if k < 0 then
    begin
      if nums[left] = 0 then
        k += 1;
      left += 1;
    end;
  end;

  Result := nums.Length - left;
end;

