  var currentGap := 0;

  foreach var b in binary do
  begin
    if b = '1' then
    begin
      if currentGap > maxGap then
        maxGap := currentGap;
      currentGap := 0;
    end
    else
      currentGap += 1;
  end;

  Result := maxGap;
end;

function MaxConsecutiveOnes(nums: array of integer; k: integer): integer;
begin
  var left := 0;
  var maxLength := 0;
  var zeroCount := 0;

  for var right := 0 to nums.Length - 1 do
  begin
    if nums[right] = 0 then
      zeroCount += 1;

    while zeroCount > k do
    begin
      if nums[left] = 0 then
        zeroCount -= 1;
      left += 1;
    end;

    maxLength := Max(maxLength, right - left + 1);
  end;

  Result := maxLength;
end;

