function NormalizeStrings(strings: array of string): List<string>;
begin
  var normalizedStrings := new List<string>;
  foreach var str in strings do
    normalizedStrings.Add(str.Trim.ToLower);
  Result := normalizedStrings;
end;

function FindMaxOperations(nums: array of integer; k: integer): integer;
begin
  var mp := new Dictionary<integer, integer>;
  var ans := 0;

  foreach var i in nums do
  begin
    if i >= k then
      continue;

    var m := k - i;
    if mp.ContainsKey(m) and (mp[m] >= 1) then
    begin
      ans += 1;
      mp[m] -= 1;
    end
    else
    begin
      if mp.ContainsKey(i) then
        mp[i] += 1
      else
        mp[i] := 1;
    end;
  end;

  Result := ans;
end;

function MinimumDeletions(s: string): integer;
begin
  var aCount := 0;
  var bCount := 0;

  foreach var ch in s do
  begin
    if ch = 'a' then
      aCount += 1
    else
      bCount += 1;
  end;

  if aCount = bCount then
  begin
    Result := 0;
    exit;
  end;

  Result := Abs(aCount - bCount);
end;

function CheckPerfectSquare(n: integer): string;
begin
  var sqrt := Round(Sqrt(n));
  if sqrt * sqrt = n then
    Result := 'Yes'
  else
    Result := 'No';
end;

function FindGoodPairs(nums: array of integer): integer;
begin
  var freq := new Dictionary<integer, integer>;
  var pairs := 0;

  foreach var x in nums do
  begin
    if freq.ContainsKey(x) then
      freq[x] += 1
    else
      freq[x] := 1;
  end;

  foreach var kv in freq do
  begin
    var pair := kv.Value * (kv.Value - 1) div 2;
    pairs += pair;
  end;

  Result := pairs;
end;

function GetMaxLength(nums: array of integer; startIndex: integer): integer;
begin
  var j := startIndex;
  var n := 0;
  var max1 := 0;
  var n_s := -1;
  var n_e := -1;

  while (j < nums.Length) and (nums[j] <> 0) do
  begin
    if nums[j] < 0 then
    begin
      if n_s = -1 then
        n_s := j;
      n_e := j;
      n += 1;
    end;

    if n mod 2 = 0 then
      max1 := Max(max1, j - startIndex + 1)
    else
    begin
      max1 := Max(max1, j - n_s);
      max1 := Max(max1, n_e - startIndex);
    end;
    j += 1;
  end;

  if (j + 1 < nums.Length - 1) then
    Result := Max(max1, GetMaxLength(nums, j + 1))
  else
    Result := max1;
end;

function MaxPositiveProduct(nums: array of integer): integer;
begin
  Result := GetMaxLength(nums, 0);
end;

function PartitionEqual(arr: array of integer): boolean;
begin
  var total := arr.Sum;
  if total mod 2 <> 0 then
  begin
    Result := false;
    exit;
  end;

  var target := total div 2;
  var dp := ArrFill(target + 1, false);
  dp[0] := true;

  foreach var num in arr do
    for var i := target downto num do
      dp[i] := dp[i] or dp[i - num];

  Result := dp[target];
end;

function FindNumberOccurrences(arr: array of integer; num: integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var left := 0;
  var right := arr.Length - 1;

  while left < right do
  begin
    var mid := left + (right - left) div 2;
    if arr[mid] < num then
      left := mid + 1
    else
      right := mid;
  end;

  if arr[left] <> num then
  begin
    Result := 0;
    exit;
  end;

  var startIndex := left;
  right := arr.Length - 1;

  while left < right do
  begin
    var mid := left + (right - left + 1) div 2;
    if arr[mid] > num then
      right := mid - 1
    else
      left := mid;
  end;

  Result := right - startIndex + 1;
end;

function IntToBin(n: integer): string;
begin
  Result := Convert.ToString(n, 2);
end;

function HasSubarrayWithZeroSum(nums: array of integer): boolean;
begin
  var hashSet := new HashSet<integer>;
  var currentSum := 0;

  foreach var num in nums do
  begin
    currentSum += num;
    if (currentSum = 0) or hashSet.Contains(currentSum) then
    begin
      Result := true;
      exit;
    end;
    hashSet.Add(currentSum);
  end;

  Result := false;
end;

function ProperDivisorSum(n: integer): integer;
begin
  if n <= 1 then
  begin
    Result := 0;
    exit;
  end;

  var divisors := new List<integer>([1]);
  for var i := 2 to Round(Sqrt(n)) do
  begin
    if n mod i = 0 then
    begin
      if i = n div i then
        divisors.Add(i)
      else
      begin
        divisors.Add(i);
        divisors.Add(n div i);
      end;
    end;
  end;

  Result := divisors.Sum;
end;

function VolumeOfSphere(r: real): real;
begin
  Result := (4/3) * Pi * Power(r, 3);
end;

function FindMedianSortedArrays(nums1, nums2: array of integer): real;
begin
  var merged := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < nums1.Length) and (j < nums2.Length) do
  begin
    if nums1[i] < nums2[j] then
    begin
      merged.Add(nums1[i]);
      i += 1;
    end
    else
    begin
      merged.Add(nums2[j]);
      j += 1;
    end;
  end;

  while i < nums1.Length do
  begin
    merged.Add(nums1[i]);
    i += 1;
  end;

  while j < nums2.Length do
  begin
    merged.Add(nums2[j]);
    j += 1;
  end;

  var n := merged.Count;
  if n mod 2 = 0 then
    Result := (merged[n div 2 - 1] + merged[n div 2]) / 2
  else
    Result := merged[n div 2];
end;

function FindDuplicateNumber(nums: array of integer): integer;
begin
  var i := 0;
  while i < nums.Length do
  begin
    if nums[i] = i then
    begin
      i += 1;
      continue;
    end;
    if nums[nums[i]] = nums[i] then
    begin
      Result := nums[i];
      exit;
    end;
    var temp := nums[nums[i]];
    nums[nums[i]] := nums[i];
    nums[i] := temp;
  end;
  Result := -1;
end;

function NthFibonacci(n: integer): integer;
begin
  if n = 0 then
    Result := 0
  else if n = 1 then
    Result := 1
  else
  begin
    var a := 0;
    var b := 1;
    for var i := 2 to n do
    begin
      var temp := a + b;
      a := b;
      b := temp;
    end;
    Result := b;
  end;
end;

function SmallestMissingPos(list1: array of integer): integer;
begin
  var positiveList := list1.Where(i -> i > 0).ToList;
  positiveList.Sort;

  if positiveList.Count = 0 then
  begin
    Result := 1;
    exit;
  end;

  if positiveList[0] > 1 then
  begin
    Result := 1;
    exit;
  end;

  for var i := 0 to positiveList.Count - 2 do
  begin
    if positiveList[i + 1] - positiveList[i] > 1 then
    begin
      Result := positiveList[i] + 1;
      exit;
    end;
  end;

  Result := positiveList[positiveList.Count - 1] + 1;
end;

function Dfs(index, count: integer; hasPre, root: boolean; const slices: array of integer): integer;
begin
  if index = slices.Length then
  begin
    if (count <> slices.Length div 3) or (hasPre and root) then
      Result := integer.MinValue
    else
      Result := 0;
    exit;
  end;

  var res := Dfs(index + 1, count, false, root, slices);
  if (not hasPre) and (count + 1 <= slices.Length div 3) then
    res := Max(res, Dfs(index + 1, count + 1, true, root, slices) + slices[index]);

  Result := res;
end;

function MaxSizeSlices(slices: array of integer): integer;
begin
  var n := slices.Length;
  Result := Max(Dfs(1, 1, true, true, slices) + slices[0], Dfs(1, 0, false, false, slices));
end;

function Distance(pointX, pointY: (real, real)): real;
begin
  Result := Sqrt(Power(pointX.Item1 - pointY.Item1, 2) + Power(pointX.Item2 - pointY.Item2, 2));
end;

function IsMiddle(pointX2, pointY2: ((real, real), (real, real))): boolean;
begin
  Result := ((pointX2.Item1.Item1 + pointX2.Item2.Item1) / 2 = (pointY2.Item1.Item1 + pointY2.Item2.Item1) / 2) and
            ((pointX2.Item1.Item2 + pointX2.Item2.Item2) / 2 = (pointY2.Item1.Item2 + pointY2.Item2.Item2) / 2);
end;

function MinAreaFreeRect(points: array of (real, real)): real;
begin
  var dictsDistance := new Dictionary<real, List<((real, real), (real, real))>>;

  for var i := 0 to points.Length - 1 do
    for var j := i + 1 to points.Length - 1 do
    begin
      var pointsDistance := Distance(points[i], points[j]);
      if not dictsDistance.ContainsKey(pointsDistance) then
        dictsDistance[pointsDistance] := new List<((real, real), (real, real))>;
      dictsDistance[pointsDistance].Add((points[i], points[j]));
    end;

  var minArea := real.MaxValue;

  foreach var key in dictsDistance.Keys do
  begin
    if dictsDistance[key].Count < 2 then
      continue;

    for var i1 := 0 to dictsDistance[key].Count - 2 do
      for var i2 := i1 + 1 to dictsDistance[key].Count - 1 do
      begin
        var points4 := Arr(dictsDistance[key][i1], dictsDistance[key][i2]);
        if IsMiddle(points4[0], points4[1]) then
        begin
          var p2 := points4[0].Item1;
          var (p1, p3) := points4[1];
          var area := Distance(p2, p1) * Distance(p2, p3);
          minArea := Min(minArea, area);
        end;
      end;
  end;

  if minArea = real.MaxValue then
    Result := 0
  else
    Result := minArea;
end;

function CyclicSort(nums: array of integer): boolean;
begin
  var n := nums.Length;
  if n <= 1 then
  begin
    Result := true;
    exit;
  end;

  var disordered := 0;
  for var i := 1 to n - 1 do
  begin
    if nums[i-1] > nums[i] then
      disordered += 1;
  end;

  if nums[n-1] > nums[0] then
    disordered += 1;

  Result := disordered <= 1;
end;

function DoRectanglesIntersect(rect1, rect2: (real, real, real, real)): boolean;
begin
  var (x1, y1, x2, y2) := rect1;
  var (p, q, r, s) := rect2;

  if (x2 < p) or (r < x1) or (y2 < q) or (s < y1) then
    Result := false
  else
    Result := true;
end;

function FindFirstRecurringChar(s: string): char;
begin
  var seen := new HashSet<char>;
  foreach var ch in s do
  begin
    if seen.Contains(ch) then
    begin
      Result := ch;
      exit;
    end;
    seen.Add(ch);
  end;
  Result := #0;
end;

function HasUniqueCharacters(s: string): boolean;
begin
  var seen := new HashSet<char>;
  foreach var ch in s do
  begin
    if seen.Contains(ch) then
    begin
      Result := false;
      exit;
    end;
    seen.Add(ch);
  end;
  Result := true;
end;

function IsDigitOnly(str1: string): boolean;
begin
  Result := str1.All(ch -> ch in ['0'..'9']);
end;

function PascalsTriangleRow(n: integer): array of integer;
begin
  var res := ArrFill(n + 1, 0);
  res[0] := 1;

  for var i := 1 to n do
  begin
    var pre := res.ToArray;
    for var j := 1 to i do
      res[j] := pre[j-1] + pre[j];
  end;

  Result := res;
end;

function TimeToMinutesSeconds(totalSeconds: integer): (string, string);
begin
  var minutes := totalSeconds div 60;
  var seconds := totalSeconds mod 60;
  Result := (minutes.ToString + ' minutes', seconds.ToString + ' seconds');
end;

procedure ApplyOperator(operands: List<integer>; op: char);
begin
  var b := operands[operands.Count - 1];
  operands.RemoveAt(operands.Count - 1);
  var a := operands[operands.Count - 1];
  operands.RemoveAt(operands.Count - 1);

  case op of
    '+': operands.Add(a + b);
    '-': operands.Add(a - b);
    '*': operands.Add(a * b);
    '/': operands.Add(a div b);
  end;
end;

function GreaterPrecedence(op1, op2: char): boolean;
begin
  var precedence := new Dictionary<char, integer>;
  precedence['+'] := 1; precedence['-'] := 1;
  precedence['*'] := 2; precedence['/'] := 2;
  Result := precedence[op1] > precedence[op2];
end;

function Evaluate(expr: string): integer;
begin
  var operands := new List<integer>;
  var operators := new List<char>;
  var i := 0;

  while i < expr.Length do
  begin
    if expr[i + 1] = ' ' then
    begin
      i += 1;
      continue;
    end;

    if expr[i + 1].IsDigit then
    begin
      var val := 0;
      while (i < expr.Length) and expr[i + 1].IsDigit do
      begin
        val := (val * 10) + StrToInt(expr[i + 1]);
        i += 1;
      end;
      operands.Add(val);
      continue;
    end
    else if expr[i + 1] = '(' then
      operators.Add(expr[i + 1])
    else if expr[i + 1] = ')' then
    begin
      while operators[operators.Count - 1] <> '(' do
      begin
        ApplyOperator(operands, operators[operators.Count - 1]);
        operators.RemoveAt(operators.Count - 1);
      end;
      operators.RemoveAt(operators.Count - 1);
    end
    else
    begin
      while (operators.Count > 0) and (operators[operators.Count - 1] <> '(') and
            GreaterPrecedence(operators[operators.Count - 1], expr[i + 1]) do
      begin
        ApplyOperator(operands, operators[operators.Count - 1]);
        operators.RemoveAt(operators.Count - 1);
      end;
      operators.Add(expr[i + 1]);
    end;
    i += 1;
  end;

  while operators.Count > 0 do
  begin
    ApplyOperator(operands, operators[operators.Count - 1]);
    operators.RemoveAt(operators.Count - 1);
  end;

  Result := operands[0];
end;

function CalculateExpression(expression: string): integer;
begin
  Result := Evaluate(expression.Replace(' ', ''));
end;

function LucasNumber(n: integer): integer;
begin
  if n = 0 then
    Result := 2
  else if n = 1 then
    Result := 1
  else
  begin
    var lucas := ArrFill(n + 1, 0);
    lucas[0] := 2;
    lucas[1] := 1;
    for var i := 2 to n do
      lucas[i] := lucas[i-1] + lucas[i-2];
    Result := lucas[n];
  end;
end;

function MaxKSumPairs(nums: array of integer; k: integer): integer;
begin
  var count := 0;
  var pairs := 0;
  var tempNums := nums.ToList;
  tempNums.Sort;
  var left := 0;
  var right := tempNums.Count - 1;

  while left < right do
  begin
    if tempNums[left] + tempNums[right] = k then
    begin
      pairs += 1;
      left += 1;
      right -= 1;
    end
    else if tempNums[left] + tempNums[right] < k then
      left += 1
    else
      right -= 1;
  end;

  Result := pairs;
end;

function FindSecondHighest(lst: array of integer): integer;
begin
  if lst.Length < 2 then
  begin
    Result := -1;
    exit;
  end;

  var highest := integer.MinValue;
  var secondHighest := integer.MinValue;

  foreach var num in lst do
  begin
    if num > highest then
    begin
      secondHighest := highest;
      highest := num;
    end
    else if (num > secondHighest) and (num <> highest) then
      secondHighest := num;
  end;

  if secondHighest = integer.MinValue then
    Result := -1
  else
    Result := secondHighest;
end;

function ConvertList(lst: array of string): List<integer>;
begin
  var res := new List<integer>;
  foreach var i in lst do
    res.Add(StrToInt(i));
  Result := res;
end;

function LengthOfLongestValidParentheses(s: string): integer;
begin
  var maxLen := 0;
  var stack := new List<integer>;
  stack.Add(-1);

  for var i := 0 to s.Length - 1 do
  begin
    if s[i + 1] = '(' then
      stack.Add(i)
    else
    begin
      stack.RemoveAt(stack.Count - 1);
      if stack.Count = 0 then
        stack.Add(i)
      else
        maxLen := Max(maxLen, i - stack[stack.Count - 1]);
    end;
  end;

  Result := maxLen;
end;

function IsArithmeticPermutation(lst: array of integer): boolean;
begin
  if lst.Length < 2 then
  begin
    Result := false;
    exit;
  end;

  var sortedLst := lst.ToList;
  sortedLst.Sort;
  var diff := sortedLst[1] - sortedLst[0];

  for var i := 2 to sortedLst.Count - 1 do
    if sortedLst[i] - sortedLst[i-1] <> diff then
    begin
      Result := false;
      exit;
    end;

  Result := true;
end;

function MaxSecondValue(lst: List<(integer, integer)>): integer;
begin
  Result := lst.Max(t -> t.Item2);
end;

function FindMaxChar(s: string): char;
begin
  var charCount := new Dictionary<char, integer>;
  var maxChar := #0;
  var maxFreq := 0;

  foreach var ch in s do
  begin
    if charCount.ContainsKey(ch) then
      charCount[ch] += 1
    else
      charCount[ch] := 1;

    if charCount[ch] > maxFreq then
    begin
      maxFreq := charCount[ch];
      maxChar := ch;
    end;
  end;

  Result := maxChar;
end;

function ClosestSquareRoot(x: integer): integer;
begin
  if x = 0 then
  begin
    Result := 0;
    exit;
  end;

  var curNum := 2;
  var prevNum := 1;

  for var i := 1 to x div 2 do
  begin
    if curNum * curNum > x then
      break;
    curNum += 1;
    prevNum += 1;
  end;

  if curNum * curNum = x then
    Result := curNum
  else
    Result := prevNum;
end;

function IsPrime(n: integer): boolean;
begin
  if n < 2 then
  begin
    Result := false;
    exit;
  end;
  for var i := 2 to Round(Sqrt(n)) do
    if n mod i = 0 then
    begin
      Result := false;
      exit;
    end;
  Result := true;
end;

function SmallestPrime(numbers: array of integer): integer;
begin
  var primes := new List<integer>;
  foreach var num in numbers do
    if IsPrime(num) then
      primes.Add(num);

  if primes.Count > 0 then
    Result := primes.Min
  else
    Result := -1;
end;

procedure Dfs(var grid: array of array of integer; i, j: integer);
begin
  if (i < 0) or (i >= grid.Length) or (j < 0) or (j >= grid[0].Length) or (grid[i][j] <> 1) then
    exit;

  grid[i][j] := -1;
  Dfs(grid, i+1, j);
  Dfs(grid, i-1, j);
  Dfs(grid, i, j+1);
  Dfs(grid, i, j-1);
end;

function IslandCounter(grid: array of array of integer): integer;
begin
  var islands := 0;
  for var i := 0 to grid.Length - 1 do
    for var j := 0 to grid[0].Length - 1 do
      if grid[i][j] = 1 then
      begin
        Dfs(grid, i, j);
        islands += 1;
      end;

  Result := islands;
end;

function IntegerSquareRoot(n: integer): integer;
begin
  if n < 0 then
    raise new System.ArgumentException('n must be non-negative');

  var x := n;
  var y := (x + 1) div 2;

  while y < x do
  begin
    x := y;
    y := (x + n div x) div 2;
  end;

  Result := x;
end;

function CountDecoding(s: string): integer;
begin
  if (s.Length = 0) or (s[1] = '0') then
  begin
    Result := 0;
    exit;
  end;

  var n := s.Length;
  var dp := ArrFill(n + 1, 0);
  dp[0] := 1;
  dp[1] := 1;

  for var i := 2 to n do
  begin
    var single := StrToInt(s[i].ToString);
    var double := StrToInt(s.Substring(i-1, 2));

    if (single >= 1) and (single <= 9) then
      dp[i] += dp[i - 1];

    if (double >= 10) and (double <= 26) then
      dp[i] += dp[i - 2];
  end;

  Result := dp[n];
end;

function TotalSubarrays(nums: array of integer; k: integer): integer;
begin
  var kCount := 0;
  var s := 0;
  var countBySum := new Dictionary<integer, integer>;
  countBySum[0] := 1;

  foreach var num in nums do
  begin
    s += num;
    if countBySum.ContainsKey(s - k) then
      kCount += countBySum[s - k];

    if countBySum.ContainsKey(s) then
      countBySum[s] += 1
    else
      countBySum[s] := 1;
  end;

  Result := kCount;
end;

function SumEvenProductOdd(numbers: array of integer): (integer, integer);
begin
  var sumEven := 0;
  var productOdd := 1;
  var hasOdd := false;

  foreach var number in numbers do
  begin
    if number mod 2 = 0 then
      sumEven += number
    else
    begin
      productOdd *= number;
      hasOdd := true;
    end;
  end;

  if not hasOdd then
    productOdd := 1;

  Result := (sumEven, productOdd);
end;

function RunningSum(nums: array of integer): List<integer>;
begin
  var res := new List<integer>;
  var total := 0;

  foreach var num in nums do
  begin
    total += num;
    res.Add(total);
  end;

  Result := res;
end;

function Helper(l, r: integer; delete: boolean; const s: string): boolean;
begin
  while l < r do
  begin
    if s[l + 1] <> s[r + 1] then
    begin
      if delete then
        Result := Helper(l, r-1, false, s) or Helper(l+1, r, false, s)
      else
        Result := false;
      exit;
    end;
    l += 1;
    r -= 1;
  end;
  Result := true;
end;

function IsAlmostPalindrome(s: string): boolean;
begin
  Result := Helper(0, s.Length - 1, true, s);
end;

function IntFromList(lst: array of integer): integer;
begin
  var numStr := string.Join('', lst.Select(x -> x.ToString));
  Result := StrToInt(numStr);
end;

function FindLongestLength(strings: array of string): integer;
begin
  if strings.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  Result := strings.Max(s -> s.Length);
end;

function NumConsecutiveSum(n: integer): integer;
begin
  var count := 0;
  for var i := 1 to Round(Sqrt(2 * n)) do
  begin
    if (n - (i * (i - 1) div 2)) mod i = 0 then
    begin
      var value := (n - (i * (i - 1) div 2)) div i;
      if value > 0 then
        count += 1;
    end;
  end;
  Result := count;
end;

function NewtonSquareRoot(num: real): real;
begin
  if num < 0 then
  begin
    Result := -1;
    exit;
  end;

  var precision := 0.00000001;
  var x: real;

  if num < 1 then
    x := num
  else
    x := num / 2;

  while true do
  begin
    var nextX := (x + num / x) / 2;
    if Abs(nextX - x) < precision then
    begin
      Result := nextX;
      exit;
    end;
    x := nextX;
  end;
end;

function RotList(lst: array of integer; num: integer): List<integer>;
begin
  var n := lst.Length;
  var actualNum := num mod n;
