function FindNumberOccurrences(arr: array of integer; num: integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var left := 0;
  var right := arr.Length - 1;

  while left < right do
  begin
    var mid := left + (right - left) div 2;
    if arr[mid] < num then
      left := mid + 1
    else
      right := mid;
  end;

  if arr[left] <> num then
  begin
    Result := 0;
    exit;
  end;

  var startIndex := left;
  right := arr.Length - 1;

  while left < right do
  begin
    var mid := left + (right - left + 1) div 2;
    if arr[mid] > num then
      right := mid - 1
    else
      left := mid;
  end;

  Result := right - startIndex + 1;
end;

