procedure BacktrackBinary(n: integer; combination: List<integer>; var result: List<List<integer>>);
begin
  if combination.Count = n then
  begin
    result.Add(new List<integer>(combination));
    exit;
  end;

  for var i := 0 to 1 do
  begin
    combination.Add(i);
    BacktrackBinary(n, combination, result);
    combination.RemoveAt(combination.Count - 1);
  end;
end;

