  var m := X.Length;
  var n := Y.Length;
  var L := new integer[m+1, n+1];

  for var i := 0 to m do
    for var j := 0 to n do
      if (i = 0) or (j = 0) then
        L[i,j] := 0
      else if X[i] = Y[j] then
        L[i,j] := L[i-1,j-1] + 1
      else
        L[i,j] := Max(L[i-1,j], L[i,j-1]);

  Result := L[m,n];
end;

function ExtractOddNumbers(numbers: array of integer): array of integer;
