function MaxWaterArea(height: array of integer): integer;
begin
  var left := 0;
  var right := height.Length - 1;
  var maxArea := 0;

  while left < right do
  begin
    var width := right - left;
    if height[left] <= height[right] then
    begin
      maxArea := Max(maxArea, height[left] * width);
      left += 1;
    end
    else
    begin
      maxArea := Max(maxArea, height[right] * width);
      right -= 1;
    end;
  end;

  Result := maxArea;
end;

function FindSumWays(n: integer): integer;
begin
  if (n = 1) or (n = 2) then
    Result := 1
  else if n = 3 then
    Result := 2
  else
  begin
    var dp := new integer[n+1];
    dp[1] := 1;
    dp[2] := 1;
    dp[3] := 2;
    for var i := 4 to n do
      dp[i] := dp[i-1] + dp[i-3] + dp[i-4];
    Result := dp[n];
  end;
end;

function OperationsToEqual(str1, str2: string): integer;
begin
  var m := str1.Length;
  var n := str2.Length;
  var dp := new integer[m+1, n+1];

  for var i := 0 to m do
    for var j := 0 to n do
      if (i = 0) or (j = 0) then
        dp[i,j] := i + j
      else if str1[i] = str2[j] then
        dp[i,j] := dp[i-1,j-1]
      else
        dp[i,j] := 1 + Min(dp[i,j-1], dp[i-1,j]);

  Result := dp[m,n];
end;

function CheckBinaryTree(preorder: string): boolean;
begin
  var nodes := preorder.Split(',').ToList;
  if nodes[0] = '#' then
  begin
    if nodes.Count = 1 then
      Result := True
    else
      Result := False;
    exit;
  end;

  var stack := new Stack<integer>;
  for var i := 0 to nodes.Count - 1 do
  begin
    var ch := nodes[i];
    if ch = '#' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Push(stack.Pop - 1);
      while (stack.Count > 0) and (stack.Peek <= 0) do
      begin
        stack.Pop;
        if stack.Count > 0 then
          stack.Push(stack.Pop - 1);
      end;
    end
    else
    begin
      if (i <> 0) and (stack.Count = 0) then
      begin
        Result := False;
        exit;
      end;
      stack.Push(2);
    end;
  end;

  Result := stack.Count = 0;
end;

function DecimalToTernary(n: integer): integer;
