function FibMemoizedInternal(n: integer; var cache: Dictionary<integer, integer>): integer;
begin
  if n = 0 then
  begin
    Result := 0;
    exit;
  end
  else if n = 1 then
  begin
    Result := 1;
    exit;
  end;

  if cache.ContainsKey(n) then
  begin
    Result := cache[n];
    exit;
  end;

  cache[n] := FibMemoizedInternal(n - 1, cache) + FibMemoizedInternal(n - 2, cache);
  Result := cache[n];
end;

function FibMemoized(n: integer): integer;
begin
  var cache := new Dictionary<integer, integer>;
