function NearlyIdentical(str1, str2: string): boolean;
begin
  var c1 := new Dictionary<char, integer>;
  var c2 := new Dictionary<char, integer>;

  foreach var ch in str1 do
    if c1.ContainsKey(ch) then
      c1[ch] += 1
    else
      c1.Add(ch, 1);

  foreach var ch in str2 do
    if c2.ContainsKey(ch) then
      c2[ch] += 1
    else
      c2.Add(ch, 1);

  if not c1.Keys.ToHashSet.SetEquals(c2.Keys.ToHashSet) then
  begin
    Result := False;
    exit;
  end;

  var values1 := c1.Values.ToList;
  var values2 := c2.Values.ToList;
  values1.Sort;
  values2.Sort;

  if not values1.SequenceEqual(values2) then
  begin
