  begin
    if not numSet.Contains(num - 1) then
    begin
      var currentLength := 1;
      var currentNum := num;

      while numSet.Contains(currentNum + 1) do
      begin
        currentNum += 1;
        currentLength += 1;
      end;

      if currentLength > longestLength then
      begin
        longestLength := currentLength;
        longestRange[0] := num;
        longestRange[1] := currentNum;
      end;
    end;
  end;

  Result := longestRange;
end;

function PrimeIndices(nums: array of integer): array of integer;

  function IsPrime(n: integer): boolean;
  begin
    if n <= 1 then
      Result := False
    else if n = 2 then
      Result := True
    else if n mod 2 = 0 then
      Result := False
    else
    begin
      var i := 3;
      while i * i <= n do
      begin
        if n mod i = 0 then
        begin
          Result := False;
          exit;
        end;
        i += 2;
      end;
      Result := True;
    end;
  end;

begin
  var res := new List<integer>;
  for var i := 0 to nums.Length - 1 do
    if IsPrime(nums[i]) then
      res.Add(i);
  Result := res.ToArray;
end;

function MaxArea(height: array of integer): integer;
begin
  var maxArea := 0;
  var left := 0;
  var right := height.Length - 1;

  while left < right do
  begin
    maxArea := Max(maxArea, Min(height[left], height[right]) * (right - left));
    if height[left] > height[right] then
      right -= 1
    else
      left += 1;
  end;

  Result := maxArea;
end;

