function PrimeFib(n: integer): integer;

  function CheckPrime(num: integer): boolean;
  begin
    if num <= 1 then
      Result := False
    else if num = 2 then
      Result := True
    else if num mod 2 = 0 then
      Result := False
    else
    begin
      var i := 3;
      while i * i <= num do
      begin
        if num mod i = 0 then
        begin
          Result := False;
          exit;
        end;
        i += 2;
      end;
      Result := True;
    end;
  end;

  function Fib(k: integer): integer;
  begin
    if k <= 1 then
      Result := k
    else
    begin
      var a := 0;
      var b := 1;
      for var i := 2 to k do
      begin
        var temp := a + b;
        a := b;
        b := temp;
      end;
      Result := b;
    end;
  end;

begin
  var i := 0;
  var count := 0;
  while True do
  begin
    var fib_i := Fib(i);
    if CheckPrime(fib_i) then
    begin
      count += 1;
      if count = n then
      begin
        Result := fib_i;
        exit;
      end;
    end;
    i += 1;
  end;
end;

