    var k := i + 2;
    for var j := i + 1 to sortedSides.Count - 2 do
    begin
      while (k < sortedSides.Count) and (sortedSides[i] + sortedSides[j] > sortedSides[k]) do
        k += 1;
      count += k - j - 1;
    end;
  end;

  Result := count;
end;

