        xy += 1;

  var yz := 0;
  for var j := 0 to grid[0].Length - 1 do
  begin
    var maxVal := 0;
    for var i := 0 to grid.Length - 1 do
      maxVal := Max(maxVal, grid[i][j]);
    yz += maxVal;
  end;

  var zx := 0;
  for var i := 0 to grid.Length - 1 do
  begin
    var maxVal := 0;
    for var j := 0 to grid[i].Length - 1 do
      maxVal := Max(maxVal, grid[i][j]);
    zx += maxVal;
  end;

  Result := xy + yz + zx;
end;

