function MatrixReshape(mat: array [,] of integer; r, c: integer): array [,] of integer;
begin
  var m := mat.GetLength(0);
  var n := mat.GetLength(1);

  if m * n <> r * c then
  begin
    Result := mat;
    exit;
  end;

  var output := new integer[r, c];
  var x := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      output[x div c, x mod c] := mat[i, j];
      x += 1;
    end;

  Result := output;
end;

function NChooseK(n, k: integer): integer;
begin
  if k > n then
  begin
    Result := 0;
    exit;
  end;

  if (k = 0) or (k = n) then
  begin
    Result := 1;
    exit;
  end;

  k := Min(k, n - k);
  var numerator := 1;

  for var i := n downto n - k + 1 do
    numerator := numerator * i;

  var denominator := 1;
  for var i := 1 to k do
    denominator := denominator * i;

  Result := numerator div denominator;
end;

function FindLongestCommonSubarray(nums1, nums2: array of integer): integer;
begin
  var answer := 0;

  if nums1.Length < nums2.Length then
  begin
    var temp := nums1;
    nums1 := nums2;
    nums2 := temp;
  end;

  var deque1 := new Queue<integer>(nums1);
  var deque2 := new Queue<integer>(nums2);

  for var i := 1 to nums2.Length - 1 do
  begin
    deque1.Enqueue(-1);
    deque1.Enqueue(-1);
  end;
  deque1.Enqueue(-1);

  for var i := 0 to deque1.Count - nums2.Length do
  begin
    deque1.Dequeue;
    var count := 0;
    var flag := false;

    for var j := 0 to nums2.Length - 1 do
    begin
      if deque1.ElementAt(j) = deque2.ElementAt(j) then
      begin
        if not flag then
          flag := true;
        count += 1;
      end
      else
      begin
        count := 0;
        flag := false;
      end;
      answer := Max(answer, count);
    end;
  end;

  Result := answer;
end;

function ClosestThreeSum(nums: array of integer; target: integer): integer;
begin
  &Array.Sort(nums);
  var closest := 1000000;

  for var idx := 0 to nums.Length - 3 do
  begin
    if (idx = 0) or (nums[idx] <> nums[idx - 1]) then
    begin
      var left := idx + 1;
      var right := nums.Length - 1;

      while left < right do
      begin
        var total := nums[idx] + nums[left] + nums[right];
        if Abs(closest - target) > Abs(total - target) then
          closest := total;

        if total > target then
          right -= 1
        else if total < target then
          left += 1
        else
        begin
          Result := target;
          exit;
        end;
      end;
    end;
  end;

  Result := closest;
end;

