  begin
    var (x, y) := pairs[i];
    sim.Add((x, y));
    sim.Add((y, x));
  end;

  if words1.Length <> words2.Length then
  begin
    Result := false;
    exit;
  end;

  for var i := 0 to words1.Length - 1 do
  begin
    var x := words1[i];
    var y := words2[i];

    if (x <> y) and (not sim.Contains((x, y))) then
    begin
      Result := false;
      exit;
    end;
  end;

  Result := true;
end;

function UniquePaths(m, n: integer): integer;
begin
  if (m = 0) or (n = 0) then
  begin
    Result := 0;
    exit;
  end;

  var dp := new integer[m, n];

  for var i := 0 to m - 1 do
    dp[i, 0] := 1;

  for var j := 0 to n - 1 do
    dp[0, j] := 1;

  for var i := 1 to m - 1 do
    for var j := 1 to n - 1 do
      dp[i, j] := dp[i - 1, j] + dp[i, j - 1];

  Result := dp[m - 1, n - 1];
end;

