function FindLHS(nums: array of integer): integer;
begin
  var count := new Dictionary<integer, integer>;

  for var i := 0 to nums.Length - 1 do
  begin
    if not count.ContainsKey(nums[i]) then
      count[nums[i]] := 0;
    count[nums[i]] += 1;
  end;

  var longest := 0;

  foreach var k in count.Keys do
  begin
    if count.ContainsKey(k + 1) then
      longest := Max(longest, count[k] + count[k + 1]);
  end;

  Result := longest;
end;

