  var digits := new List<integer>;
  var temp := n;

  while temp > 0 do
  begin
    digits.Add(temp mod 10);
    temp := temp div 10;
  end;

  if digits.Count <> digits.Distinct.Count then
    Result := n
  else
    Result := digits.Sum;
end;

