  var sumValue := 0;
  var maxLeft := mid;

  for var i := mid downto low do
  begin
    sumValue := sumValue + arr[i];
    if sumValue > leftSum then
    begin
      leftSum := sumValue;
      maxLeft := i;
    end;
  end;

  var rightSum := integer.MinValue;
  sumValue := 0;
  var maxRight := mid + 1;

  for var j := mid + 1 to high do
  begin
    sumValue := sumValue + arr[j];
    if sumValue > rightSum then
    begin
      rightSum := sumValue;
      maxRight := j;
    end;
  end;

  Result := leftSum + rightSum;
end;

