  var rightmost := num mod 10;
  var count := 0;
  num := num div 10;

  while num > 0 do
  begin
    count := count + 1;
    var currentDigit := num mod 10;
    if currentDigit > rightmost then
    begin
      Result := count;
      exit;
    end;
    num := num div 10;
  end;

  Result := -1;
end;

