function MostFrequentNumbers(lst: List<integer>): List<integer>;
begin
  var counter := new Dictionary<integer, integer>;

  foreach var num in lst do
    if counter.ContainsKey(num) then
      counter[num] := counter[num] + 1
    else
      counter.Add(num, 1);

  var maxFreq := counter.Values.Max;
  var resultList := new List<integer>;

  foreach var pair in counter do
    if pair.Value = maxFreq then
      resultList.Add(pair.Key);

  resultList.Sort;
  Result := resultList;
end;

function DistSq(point1, point2: (integer, integer)): integer;
begin
  Result := (point1.Item1 - point2.Item1) * (point1.Item1 - point2.Item1) + 
            (point1.Item2 - point2.Item2) * (point1.Item2 - point2.Item2);
end;

function ValidRectangle(p1, p2, p3, p4: (integer, integer)): boolean;
