  var points := new List<(integer, integer)>;
  points.Add(p1);
  points.Add(p2);
  points.Add(p3);
  points.Add(p4);

  var distances := new List<integer>;

  for var i := 0 to 3 do
    for var j := i + 1 to 3 do
      distances.Add(DistSq(points[i], points[j]));

  distances.Sort;

  if (distances[0] = distances[1]) and (distances[1] = distances[2]) and 
     (distances[2] = distances[3]) and (distances[4] = distances[5]) then
    Result := True
  else
    Result := False;
end;

function CanBeExpressedAsPower(n: integer): boolean;
