  var start := 0;

  while start < strVal.Length do
  begin
    var pos := strVal.IndexOf(substring, start);
    if pos <> -1 then
    begin
      count := count + 1;
      start := pos + 1;
    end
    else
      break;
  end;

  Result := count;
end;

function ValidParenthesisSequence(s: string): boolean;
begin
  var stack := new Stack<char>;

  foreach var char in s do
  begin
    if char = '(' then
      stack.Push(char)
    else if char = ')' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;

  Result := stack.Count = 0;
end;

