  var maxSum := arr[0];
  var currentSum := arr[0];

  for var i := 1 to arr.Count - 1 do
  begin
    currentSum := Max(arr[i], currentSum + arr[i]);
    maxSum := Max(maxSum, currentSum);
  end;

  Result := maxSum;
end;

function FindDuplicateCharacters(strVal: string): Dictionary<char, integer>;
begin
  var charCount := new Dictionary<char, integer>;

  foreach var char in strVal do
    if charCount.ContainsKey(char) then
      charCount[char] := charCount[char] + 1
    else
      charCount.Add(char, 1);

  var duplicates := new Dictionary<char, integer>;
  foreach var pair in charCount do
    if pair.Value > 1 then
      duplicates.Add(pair.Key, pair.Value);

  Result := duplicates;
end;

function FindLongestCommonSubstring(str1, str2: string): string;
begin
  var m := str1.Length;
  var n := str2.Length;
  var dp := new integer[m + 1, n + 1];
  var maxLen := 0;
  var endIndex := 0;

  for var i := 1 to m do
  begin
    for var j := 1 to n do
    begin
      if str1[i - 1] = str2[j - 1] then
      begin
        dp[i, j] := dp[i - 1, j - 1] + 1;
        if dp[i, j] > maxLen then
        begin
          maxLen := dp[i, j];
          endIndex := i;
        end;
      end
      else
        dp[i, j] := 0;
    end;
  end;

  if maxLen = 0 then
    Result := ''
  else
    Result := str1.Substring(endIndex - maxLen, maxLen);
end;

