function IsPrimeNumber(n: integer): boolean;
begin
  if n <= 1 then
    Result := False
  else if n <= 3 then
    Result := True
  else if (n mod 2 = 0) or (n mod 3 = 0) then
    Result := False
  else
  begin
    var i := 5;
    while i * i <= n do
    begin
      if (n mod i = 0) or (n mod (i + 2) = 0) then
      begin
        Result := False;
        exit;
      end;
      i := i + 6;
    end;
    Result := True;
  end;
end;

