function PalindromeSubstringsCount(s: string): integer;

  function ExpandAroundCenter(left: integer; right: integer): integer;
  begin
    var count := 0;
    while (left >= 0) and (right < s.Length) and (s[left] = s[right]) do
    begin
      count += 1;
      left -= 1;
      right += 1;
    end;
    Result := count;
  end;

begin
  var totalCount := 0;
  for var i := 0 to s.Length - 1 do
  begin
    totalCount += ExpandAroundCenter(i, i);
