  while (i < l1.Length) and (j < l2.Length) do
  begin
    if l1[i] < l2[j] then
    begin
      l3.Add(l1[i]);
      i += 1;
    end
    else
    begin
      l3.Add(l2[j]);
      j += 1;
    end;
  end;

  if i = l1.Length then
    l3.AddRange(l2[j:l2.Length])
  else
    l3.AddRange(l1[i:l1.Length]);

  Result := l3.ToArray();
end;

