  var heap := new List<integer>;

  for var i := 0 to nums.Length - 1 do
  begin
    heap.Add(nums[i]);

    if heap.Count > k then
    begin
      heap.Sort;
      heap.RemoveAt(0);
    end;
  end;

  heap.Sort;
  Result := heap[0];
end;

