function GCDLCM(a, b: integer): (integer, integer);
begin
  var c := Max(a, b);
  var d := Min(a, b);
  var t := 1;

  while t > 0 do
  begin
    t := c mod d;
    c := d;
    d := t;
  end;

  var gcd := c;
  var lcm := (a * b) div gcd;

  Result := (gcd, lcm);
end;

