end.
```

Here is a PascalABC.NET function that takes an integer X and prints
'Hello, World!' if X is a prime number. The time complexity of the
primality test is O(sqrt(X)):

```pascal
function IsPrime(X: integer): boolean;
begin
  if X < 2 then
  begin
    IsPrime := False;
    exit;
  end;

  if (X = 2) or (X = 3) then
  begin
    IsPrime := True;
    exit;
  end;

  if (X mod 2 = 0) or (X mod 3 = 0) then
  begin
    IsPrime := False;
    exit;
  end;

  var Divisor := 5;
  var Step := 2;
  while int64(Divisor) * Divisor <= X do
  begin
    if X mod Divisor = 0 then
    begin
      IsPrime := False;
      exit;
    end;
    Divisor += Step;
    Step := 6 - Step; // check numbers of the form 6k ± 1
  end;

  IsPrime := True;
end;

procedure PrintHelloWorldIfPrime(X: integer);
begin
  if IsPrime(X) then
    Println('Hello, World!');
end;

begin
  var X := 29;
  PrintHelloWorldIfPrime(X);
end.
```

Here is a PascalABC.NET method that takes a decimal number as text input
and returns the number of digits after the decimal separator. It validates
that the number is non-negative and does not exceed a maximum number of
fractional digits:

```pascal
function CountFractionDigits(NumberText: string; MaxDigits: integer): integer;
begin
  if string.IsNullOrWhiteSpace(NumberText) then
    raise new ArgumentException('Input cannot be empty.');

  var Trimmed := NumberText.Trim;
  if Trimmed[1] = '-' then
    raise new ArgumentException('Negative numbers are not allowed.');

  var DecimalSeparator := System.Globalization.CultureInfo.CurrentCulture.NumberFormat.NumberDecimalSeparator;
  var Parts := Trimmed.Split(DecimalSeparator.ToCharArray);

  if Parts.Length = 1 then
  begin
    CountFractionDigits := 0;
    exit;
  end;

  var FractionPart := Parts[1];
  var DigitCount := FractionPart.Length;

  if DigitCount > MaxDigits then
    raise new ArgumentException('Decimal number exceeds maximum allowed number of digits after the decimal point.');

  CountFractionDigits := DigitCount;
end;

begin
  Print('Enter a non-negative decimal number: ');
  var InputText := ReadString;
  try
    var Digits := CountFractionDigits(InputText, 5);
    Println('Number of digits after decimal point: ', Digits);
  except
    on E: Exception do
      Println('Error: ' + E.Message);
  end;
end.
```

Here is a PascalABC.NET code snippet that calculates the product of two
integers and prints the result in binary format without using built-in
conversion methods. It correctly handles negative numbers:

```pascal
function ToBinaryString(Value: int64): string;
begin
  if Value = 0 then
  begin
    ToBinaryString := '0';
    exit;
  end;

  var IsNegative := Value < 0;
  if IsNegative then
    Value := -Value;

  var Bits := '';
  while Value > 0 do
  begin
    var Bit := Value mod 2;
    Bits := Chr(Ord('0') + Bit) + Bits;
    Value := Value div 2;
  end;

  if IsNegative then
    ToBinaryString := '-' + Bits
  else
    ToBinaryString := Bits;
end;

begin
  var Num1 := 5;
  var Num2 := 7;

  var Product := int64(Num1) * Num2;
  Println($'{Num1} * {Num2} = {Product}');
  Println('Binary representation: ', ToBinaryString(Product));

  // Example with negative numbers
  Num1 := -3;
  Num2 := 4;
  Product := int64(Num1) * Num2;
  Println($'{Num1} * {Num2} = {Product}');
  Println('Binary representation: ', ToBinaryString(Product));
end.
```

Here is a PascalABC.NET program that sorts an array using the QuickSort
algorithm and then removes duplicates from the sorted array:

```pascal
procedure QuickSort(var Arr: array of integer; Left, Right: integer);
begin
  var I := Left;
  var J := Right;
  var Pivot := Arr[(Left + Right) div 2];

  while I <= J do
  begin
    while Arr[I] < Pivot do
      I += 1;
    while Arr[J] > Pivot do
      J -= 1;

    if I <= J then
    begin
      var Temp := Arr[I];
      Arr[I] := Arr[J];
      Arr[J] := Temp;
      I += 1;
      J -= 1;
    end;
  end;

  if Left < J then
    QuickSort(Arr, Left, J);
  if I < Right then
    QuickSort(Arr, I, Right);
end;

function RemoveDuplicates(const Arr: array of integer): array of integer;
begin
  if Arr.Length = 0 then
  begin
    Result := Arr;
    exit;
  end;

  var UniqueList := new List<integer>;
  var Previous := Arr[0];
  UniqueList.Add(Previous);

  for var Index := 1 to Arr.Length - 1 do
  begin
    var Current := Arr[Index];
    if Current <> Previous then
    begin
      UniqueList.Add(Current);
      Previous := Current;
    end;
  end;

  Result := UniqueList.ToArray;
end;

begin
  var Numbers := Arr(8, 4, 1, 9, 6, 4, 8, 1, 9);
  Println('Original array: ', Numbers);

  QuickSort(Numbers, 0, Numbers.Length - 1);
  Println('Sorted array:   ', Numbers);

  var Unique := RemoveDuplicates(Numbers);
  Println('Without duplicates: ', Unique);
end.
```

Here is a PascalABC.NET class that stores a student's ID, name, and a list
of course marks. It also provides a method to calculate the average mark and
