```pascal
type
  Student = class
  public
    Id: integer;
    Name: string;
    Marks: List<real>;

    constructor Create(IdValue: integer; NameValue: string);
    begin
      Id := IdValue;
      Name := NameValue;
      Marks := new List<real>;
    end;

    function AverageMark: real;
    begin
      if Marks.Count = 0 then
      begin
        AverageMark := 0.0;
        exit;
      end;

      var Sum := 0.0;
      foreach var Mark in Marks do
        Sum += Mark;

      AverageMark := Sum / Marks.Count;
    end;

    function HasPassedAllCourses(PassMark: real := 80.0): boolean;
    begin
      if Marks.Count = 0 then
      begin
        HasPassedAllCourses := False;
        exit;
      end;

      foreach var Mark in Marks do
