Here is a PascalABC.NET program that removes leading and trailing spaces,
replaces multiple consecutive spaces with a single space, capitalizes the
first letter of each word, and then replaces all occurrences of a specific
word with a different word:

```pascal
function NormalizeSpaces(SourceText: string): string;
begin
  var Parts := SourceText.Split(' ');
  var Words := new List<string>;
  foreach var Part in Parts do
    if Part <> '' then
      Words.Add(Part);
  NormalizeSpaces := string.Join(' ', Words.ToArray);
end;

function CapitalizeWords(SourceText: string): string;
begin
  if string.IsNullOrWhiteSpace(SourceText) then
  begin
    CapitalizeWords := '';
    exit;
  end;

  var Parts := SourceText.Split(' ');
  for var Index := 0 to Parts.Length - 1 do
    if Parts[Index] <> '' then
    begin
      var Word := Parts[Index];
      var Chars := Word.ToCharArray;
      Chars[0] := System.Char.ToUpper(Chars[0]);
      for var J := 1 to Chars.Length - 1 do
        Chars[J] := System.Char.ToLower(Chars[J]);
      Parts[Index] := new string(Chars);
    end;

  CapitalizeWords := string.Join(' ', Parts);
end;

begin
  var InputText := '  hello  world    how are you   ';
  var Trimmed := InputText.Trim;
  var SingleSpaced := NormalizeSpaces(Trimmed);
  var Capitalized := CapitalizeWords(SingleSpaced);
  Println('Normalized text: ', Capitalized); // "Hello World How Are You"

  Print('Enter specific word to replace (e.g. world): ');
  var SpecificWord := ReadString.ToLower;
  Print('Enter replacement word (e.g. universe): ');
  var ReplacementWord := ReadString;

  // Replace whole words ignoring case
  var Words := Capitalized.Split(' ');
  for var Index := 0 to Words.Length - 1 do
    if Words[Index].ToLower = SpecificWord then
      Words[Index] := ReplacementWord[1].ToUpper + ReplacementWord.Substring(1);

  var ResultText := string.Join(' ', Words);
  Println('Result text: ', ResultText);
end.
```

Here is a PascalABC.NET program that removes all occurrences of a given item
from a two-dimensional array of integers. It creates a new array that
contains all remaining elements while preserving their row-major order:

```pascal
function RemoveItem(const Source: array[,] of integer; ItemValue: integer): array[,] of integer;
begin
  var Rows := Source.GetLength(0);
  var Cols := Source.GetLength(1);

  var TempList := new List<integer>;
  for var I := 0 to Rows - 1 do
    for var J := 0 to Cols - 1 do
    begin
      var Value := Source[I, J];
      if Value <> ItemValue then
        TempList.Add(Value);
    end;

  if TempList.Count = 0 then
  begin
    Result := new integer[0, 0];
    exit;
  end;

  // Create a new rectangular array with one row
  var ResultCols := TempList.Count;
  var NewArr := new integer[1, ResultCols];
  for var Index := 0 to TempList.Count - 1 do
    NewArr[0, Index] := TempList[Index];

  Result := NewArr;
end;

begin
  var Data: array[,] of integer := ((1, 2, 3), (2, 2, 4), (5, 2, 6));
  Println('Original array:');
  for var I := 0 to Data.GetLength(0) - 1 do
  begin
    for var J := 0 to Data.GetLength(1) - 1 do
      Print(Data[I, J]);
    Println;
  end;

  var ItemValue := 2;
  var Cleaned := RemoveItem(Data, ItemValue);

  Println;
  Println($'Array after removing {ItemValue}:');
  for var J := 0 to Cleaned.GetLength(1) - 1 do
    Print(Cleaned[0, J]);
  Println;
end.
```

Here is a PascalABC.NET function that computes the area of a triangle given
the lengths of its three sides using Heron's formula. It checks that the
sides can form a valid triangle and demonstrates three test cases:

```pascal
function TriangleArea(A, B, C: real): real;
begin
  if (A <= 0) or (B <= 0) or (C <= 0) then
    raise new ArgumentException('Side lengths must be positive.');

  if (A + B <= C) or (A + C <= B) or (B + C <= A) then
    raise new ArgumentException('The given sides do not form a valid triangle.');

  var S := (A + B + C) / 2.0;
  var AreaSquared := S * (S - A) * (S - B) * (S - C);
  if AreaSquared < 0 then
    raise new ArgumentException('Numerical error while computing area.');

  TriangleArea := System.Math.Sqrt(AreaSquared);
end;

procedure TestTriangle(A, B, C: real);
begin
  try
    var Area := TriangleArea(A, B, C);
    Println($'Triangle({A}, {B}, {C}) area = {Area:0.000}');
  except
    on E: Exception do
      Println($'Triangle({A}, {B}, {C}) error: {E.Message}');
  end;
end;

begin
  TestTriangle(3, 4, 5);
  TestTriangle(5, 5, 8);
  TestTriangle(1, 2, 3); // invalid
end.
```

