type
  EventListener = class
  private
    eventHandlers: System.Collections.Generic.Dictionary<string, System.Delegate>;
    numEventsFired: integer;
  public
    constructor Create;
    begin
      eventHandlers := new System.Collections.Generic.Dictionary<string, System.Delegate>;
      numEventsFired := 0;
    end;

    procedure Subscribe(eventName: string; eventHandler: System.Action<array of object>);
    begin
      if not eventHandlers.ContainsKey(eventName) then
        eventHandlers[eventName] := nil;

      eventHandlers[eventName] := System.Delegate.Combine(eventHandlers[eventName], eventHandler);
    end;

    procedure Unsubscribe(eventName: string; eventHandler: System.Action<array of object>);
    begin
      if eventHandlers.ContainsKey(eventName) then
      begin
        eventHandlers[eventName] := System.Delegate.Remove(eventHandlers[eventName], eventHandler);

        if eventHandlers[eventName] = nil then
          eventHandlers.Remove(eventName);
      end;
    end;

    procedure FireEvent(eventName: string; params parameters: array of object);
    begin
      if eventHandlers.ContainsKey(eventName) then
      begin
        var eventHandler := eventHandlers[eventName];
        if eventHandler <> nil then
          eventHandler.DynamicInvoke(parameters);
        numEventsFired += 1;
      end;
    end;

    function IsSubscribed(eventName: string): boolean;
    begin
      Result := eventHandlers.ContainsKey(eventName);
    end;

    function GetSubscribedEvents: array of string;
    begin
      Result := eventHandlers.Keys.ToArray;
    end;

    function GetNumSubscribedEvents: integer;
    begin
      Result := eventHandlers.Count;
    end;

    function GetNumEventsFired: integer;
    begin
      Result := numEventsFired;
    end;
