  var numCols := arr.GetLength(1);

  var flattenedArr := new integer[numRows * numCols];
  var k := 0;

  for var i := 0 to numRows - 1 do
    for var j := 0 to numCols - 1 do
    begin
      flattenedArr[k] := arr[i, j];
      k += 1;
    end;

  System.Array.Sort(flattenedArr);

  k := 0;
  for var i := 0 to numRows - 1 do
