begin
  for var i := 0 to nums.Length - 2 do
    for var j := 0 to nums.Length - i - 2 do
    begin
      if (nums[j] mod 2 = 0) and (nums[j + 1] mod 2 = 0) and (nums[j] > nums[j + 1]) then
      begin
        var temp := nums[j];
        nums[j] := nums[j + 1];
        nums[j + 1] := temp;
