end.

function IsPrime(number: integer): boolean;
begin
  if number < 2 then
    Result := false
  else
  begin
    for var i := 2 to Round(Sqrt(number)) do
      if number mod i = 0 then
        exit(false);
    Result := true;
  end;
end;

function GenerateRandomPrime(min, max: integer): integer;
begin
  var rnd := new System.Random;
  repeat
    Result := rnd.Next(min, max + 1);
  until IsPrime(Result);
end;

